305:                                 // Mensagem de contaminação
306:                                 MessageBox.Show(gasMessage[31], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
307:                                 return;
308:                             }
309: 
310:                             String sSql = @"    Select count(s.cd_silo) 
311:                                                 from silo s, product p, TRA_Road_Destination_Silo d  
312:                                                 where s.cd_product = p.cd_product 
313:                                                 and (s.cd_product = " + cbxProductIntake.SelectedValue.ToString() + @" Or s.cd_product = 0) 
314:                                                 and (isnull(s.vl_level,' ') <> 'H' and isnull(s.vl_level,' ') <> 'A') 
315:                                                 and s.vl_fill_block <> 'Y' 
316:                                                 and d.cd_road_destination = " + cbxDestination.SelectedValue.ToString() + @"
317:                                                 and s.cd_silo = d.cd_silo ";
318: 
319:                             if (Convert.ToInt32(eData.GetSelectData(sSql)) > 0)
320:                             {
321:                                 if (gbReceivingTypeBulck)
322:                                 {
323:                                     // Executa rotinas de Start Intake do tipo granel
324:                                     priStartIntakeBulck();
325:                                 }
326:                                 else if (gbReceivingTypeBag)
327:                                 {
328:                                     // Executa rotinas de Start Intake do tipo sacos
329:                                     priStartIntakeBag();
330:                                 }
331: 
332:                                 priInitialControls();
333: 
334:                                 // Retorna os valores inciais dos combobox das rotas e dos destinos
335:                                 priRestartDestinationRoadCombobox();
336:                             }
337:                             else
338:                             {
339:                                 // Mensagem de bloqueio do silo ou produto diferente 
340:                                 MessageBox.Show(gasMessage[19] + gasMessage[18], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
341:                             }
342:                         }
343:                     }
344:                     else
345:                     {
346:                         // Mensagem de rota alternativa não selecionada 
347:                         MessageBox.Show(gasMessage[2], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
348:                     }
349:                 }
350:                 else
351:                 {
352:                     // Mostra mensagem de campos obrigatórios não preenchidos
353:                     MessageBox.Show(String.Format(gasMessage[5], lblDestination.Text + " e " + lblRoad.Text), gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
