357:             {
358:                 Utilities.Log(ex.Message.ToString() + ex.StackTrace.ToString(), @"C:\Gemba\LOG\" + Utilities.GetApplicationName(), "Log ");
359:             }

243:         private void btnStart_Click(object sender, EventArgs e)
244:         {
245:             try
246:             {
247:                 // Tira o foco do botão
248:                 lblTitle.Focus();
249: 
250:                 if ((cbxSource.SelectedIndex != -1) && (cbxDestination.SelectedIndex != -1) && (cbxRoad.SelectedIndex != -1) && (cbxProduct.SelectedIndex != -1))
251:                 {
252:                     if (((cbxDestinationAlt.SelectedIndex != -1) && (cbxRoadAlt.SelectedIndex != -1)) || ((cbxDestinationAlt.SelectedIndex == -1) || (Convert.ToInt32(cbxDestinationAlt.SelectedValue) == -1)) && (cbxRoadAlt.SelectedIndex == -1) || (cbxDestinationAlt.Text == ""))
253:                     {
254:                         Transports.Transp eTransports = new Transports.Transp(gsDataBaseFile, gsCulture, giUser);
255:                         Transports.CheckContamination eContamination = new Transports.CheckContamination(gsDataBaseFile, gsCulture, giUser);
256: 
257:                         // Verifica o intertravamento da rota e os status dos equipamentos
258:                         if (eTransports.RoadInterlockRoadEquipmentStatus(Convert.ToString(Convert.ToInt32(cbxRoad.SelectedValue)), true, true, true, Convert.ToInt32(cbxProduct.SelectedValue)))
259:                         {
260:                             if (!eContamination.pubCheckContamination(cbxRoad.SelectedValue.ToString(), Convert.ToInt32(cbxProduct.SelectedValue), 0))
261:                             {
262:                                 // Mensagem de contaminação
263:                                 MessageBox.Show(gasMessage[20], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
264:                                 return;
265:                             }
266: 
267:                             if (gbMultiparticle && (String.IsNullOrEmpty(tbxSpeed.Text) || (Convert.ToDecimal(tbxSpeed.Text) < 0 || Convert.ToDecimal(tbxSpeed.Text) > 100)))
268:                             {
269:                                 //Mensagem de velocidade fora dos limites
270:                                 MessageBox.Show(gasMessage[23], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
271:                                 return;
272:                             }
273: 
274:                             lvwMain.Enabled = false;
275: 
276:                             DtBase eData = new DtBase(gsDataBaseFile, gsCulture);
277:                             String sSql = "";
278: 
279:                             object eValues = (int)eData.NextMaxDataField("nr_production", "Silo_Transfer_Reg");
280:                             tbxProduction.Text = Convert.ToString(eValues);
281: 
282:                             // Pega o valor do stock do silo de origem
283:                             sSql = @"   Select ps_stock 
284:                                         From silo 
285:                                         Where cd_silo = " + cbxSource.SelectedValue.ToString();
286: 
287:                             Decimal dStock;
288: 
289:                             try
290:                             {
291:                                 dStock = Convert.ToDecimal(eData.GetSelectData(sSql));
292:                             }
293:                             catch (Exception)
294:                             {
295:                                 dStock = 0;
296:                             }
297: 
298:                             String sDestinationAlt;
299: 
300:                             if ((cbxDestinationAlt.SelectedIndex == -1) || (Convert.ToInt32(cbxDestinationAlt.SelectedValue) == -1))
301:                                 sDestinationAlt = "null";
302:                             else
303:                                 sDestinationAlt = cbxDestinationAlt.SelectedValue.ToString();
304: 
305:                             String sRoadAlt;
306: 
307:                             if (cbxRoadAlt.SelectedIndex == -1)
308:                                 sRoadAlt = "null";
309:                             else
310:                                 sRoadAlt = cbxRoadAlt.SelectedValue.ToString();
311: 
312:                             //Verifica o produto selecionado se é o mesmo o produto da origem ou pertence ao subproduto
313:                             sSql = String.Format(" select * from (select cd_product from Product " +
314:                                                  " where cd_subproduct_from = {0} " +
315:                                                  " union select cd_product from Product where cd_product = {0}) ListSubproduct" +
316:                                                  "  where ListSubproduct.cd_product = {1} ", gsCodeProduct, Convert.ToInt32(cbxProduct.SelectedValue));
317: 
318:                             if (!eData.HasRows(sSql))
319:                             {
320:                                 //Mensagem de contaminação

340:                                     //Verifica se existe extrusão em andamento com o destino de transilagem como origem
341:                                     sSql = String.Format(@" SELECT er.nr_production_dosing FROM Scheduling_Extruder se
342:                                                             INNER JOIN Extruder_Reg er ON er.nr_production = se.nr_production
343:                                                             WHERE se.tp_status IN ('G','S','H','A') AND se.cd_source_silo = {0} AND er.nr_production_dosing > 0", iSiloDestination);
344: 
345:                                     //Se encontrou alguma extrusão
346:                                     if (eData.HasRows(sSql))
347:                                     {
348:                                         //Guarda a OP que está sendo usada na extrusão
349:                                         int iProductionDosing = Convert.ToInt32(eData.GetSelectData(sSql));
350: 
351:                                         //Busca a produção da dosagem presente no silo de origem
352:                                         int iProductionSilo = Traceability.pubGetSiloExtruderLot(Convert.ToInt32(cbxSource.SelectedValue), gsDataBaseFile, gsCulture);
353: 
354:                                         //Verifica se a OP que está no silo de origem da transilagem é a mesma do Destino/Origem Extrusão
355:                                         if (iProductionDosing != iProductionSilo)
356:                                         {
357:                                             // Não é possível iniciar a transilagem, pois o silo de destino está com uma ordem de produção diferente. Finalize o processo de extrusão e limpe o lote no silo para dar continuidade!
358:                                             MessageBox.Show(gasMessage[25], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
359:                                             return;
360:                                         }
361:                                     }
362:                                     else
363:                                     {
364:                                         //Verifica se o silo é uma origem de extrusão
365:                                         sSql = string.Format(@" SELECT CONVERT(INTEGER, SUBSTRING(nr_lot, 2, LEN(nr_lot))) nr_lot FROM Dynamic_Silo_Trace 
366:                                                                 WHERE cd_silo IN (SELECT cd_silo FROM Extruder e
367:                                                                 				  INNER JOIN Silo_Area sa ON sa.cd_area = e.cd_area_source)
368:                                                                 AND SUBSTRING(nr_lot, 1, 1) <> 'M' AND cd_silo = {0}", iSiloDestination);
369: 
370:                                         //Se encontrou o silo como origem da extrusão
371:                                         if (eData.HasRows(sSql))
372:                                         {
373:                                             //Busca a produção da dosagem presente no silo de origem da transilagem
374:                                             int iProductionSiloSource = Traceability.pubGetSiloExtruderLot(Convert.ToInt32(cbxSource.SelectedValue), gsDataBaseFile, gsCulture);
375: 
376:                                             //Busca a produção da dosagem presente no silo destino da transilagem e origem extrusão
377:                                             int iProductionSiloDestination = Traceability.pubGetSiloExtruderLot(iSiloDestination, gsDataBaseFile, gsCulture);
378: 
379:                                             //Verifica se a OP que está no silo de origem da transilagem é a mesma do Destino/Origem Extrusão e se existe produção
380:                                             if (iProductionSiloSource != iProductionSiloDestination && iProductionSiloDestination > 0)
381:                                             {
382:                                                 // Não é possível iniciar a transilagem, pois o silo de destino está com uma ordem de produção diferente, não sendo possível misturar lotes na origem da extrusão!
383:                                                 MessageBox.Show(gasMessage[29], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
384:                                                 return;
385:                                             }
386:                                         }
387:                                     }
388:                                 }
389: 
390:                                 //Verifica se o silo alternativo possui a mesma produção que o recobridor iniciado caso não possuir o parâmetro habilitado
391:                                 if (!bEnableCoatingSourceBatchMixing)
392:                                 {
393:                                     //Verifica se existe recobridor em andamento com o destino de transilagem como origem
394:                                     sSql = String.Format(@" SELECT cr.nr_production_dosing FROM Scheduling_Coating sc
395:                                                             INNER JOIN Coating_Reg cr ON cr.nr_production = sc.nr_production
396:                                                             WHERE sc.tp_status IN ('G','S','H','A','I') AND sc.cd_source_silo = {0} AND cr.nr_production_dosing > 0", iSiloDestination);
397: 
398:                                     //Se encontrou algum recobridor
399:                                     if (eData.HasRows(sSql))
400:                                     {
401:                                         //Guarda a OP que está sendo usada no recobridor
402:                                         int iProductionDosing = Convert.ToInt32(eData.GetSelectData(sSql));
403: 
404:                                         //Busca a produção da dosagem presente no silo de origem
405:                                         int iProductionSilo = Traceability.pubGetSiloCoatingLot(Convert.ToInt32(cbxSource.SelectedValue), gsDataBaseFile, gsCulture);
406: 
407:                                         //Verifica se a OP que está no silo de origem da transilagem é a mesma do destino/Origem recobridor
408:                                         if (iProductionDosing != iProductionSilo)
409:                                         {
410:                                             // Não é possível iniciar a transilagem, pois o silo de destino está com uma ordem de produção diferente. Finalize o processo do recobridor e limpe o lote no silo para dar continuidade!
411:                                             MessageBox.Show(gasMessage[28], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
412:                                             return;
413:                                         }
414:                                     }
415:                                 }
416:                                 else
417:                                 {
418:                                     //Verifica se o silo é uma origem de recobridor
419:                                     sSql = string.Format(@" SELECT CONVERT(INTEGER, SUBSTRING(nr_lot, 2, LEN(nr_lot))) nr_lot FROM Dynamic_Silo_Trace 
420:                                                                 WHERE cd_silo IN (SELECT cd_silo FROM Coating c
421:                                                                 				  INNER JOIN Silo_Area sa ON sa.cd_area = c.cd_area_source)
422:                                                                 AND SUBSTRING(nr_lot, 1, 1) <> 'M' AND cd_silo = {0}", iSiloDestination);
423: 
424:                                     //Se encontrou o silo como origem do recobridor
425:                                     if (eData.HasRows(sSql))
426:                                     {
427:                                         //Busca a produção da dosagem presente no silo de origem da transilagem
428:                                         int iProductionSiloSource = Traceability.pubGetSiloCoatingLot(Convert.ToInt32(cbxSource.SelectedValue), gsDataBaseFile, gsCulture);
429: 
430:                                         //Busca a produção da dosagem presente no silo destino da transilagem e origem recobridor
431:                                         int iProductionSiloDestination = Traceability.pubGetSiloCoatingLot(iSiloDestination, gsDataBaseFile, gsCulture);
432: 
433:                                         //Verifica se a OP que está no silo de origem da transilagem é a mesma do Destino/Origem Recobridor e se existe uma produção
434:                                         if (iProductionSiloSource != iProductionSiloDestination && iProductionSiloDestination > 0)
435:                                         {
436:                                             // Não é possível iniciar a transilagem, pois o silo de destino está com uma ordem de produção diferente, não sendo possível misturar lotes na origem do recobridor!
437:                                             MessageBox.Show(gasMessage[30], gasMessage[1], MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
438:                                             return;
439:                                         }
440:                                     }

