587:         private void btnAux01_Click(object sender, EventArgs e)
588:         {
589:             try
590:             {
591:                 DtBase eData = new DtBase(gsDataBaseFile, gsCulture);
592:                 Transports.Transp eTransports = new Transports.Transp(gsDataBaseFile, gsCulture, this.User);
593: 
594:                 //Verifica se existe alguma extrusão selecionada para iniciar ou parar
595:                 if (lvwMain.Items.Count == 0 || string.IsNullOrEmpty(tbxProduction.Text))
596:                 {
597:                     MessageBox.Show(gasMessages[10], gasMessages[1], MessageBoxButtons.OK, MessageBoxIcon.Error);
598:                     return;
599:                 }
600: 
601:                 //Guarda as informações
602:                 int iProduction = Convert.ToInt32(tbxProduction.Text);
603:                 int iSource = Convert.ToInt32(cbxSource.SelectedValue);
604:                 int iDestination = Convert.ToInt32(cbxDestination.SelectedValue);
605:                 int iFormula = Convert.ToInt32(cbxFormula.SelectedValue);
606:                 int iProduct = Convert.ToInt32(cbxProduct.SelectedValue);
607:                 int iColorant = Convert.ToInt32(cbxColorant.SelectedValue);
608:                 int iParameter = Convert.ToInt32(cbxParameter.SelectedValue);
609:                 int iExtruder = Convert.ToInt32(cbxExtruder.SelectedValue);
610:                 string sStatus = Convert.ToString(cbxStatus.SelectedValue);
611:                 string sComment = Convert.ToString(tbxComment.Text);
612:                 string sMessage = "";
613: 
614:                 //Se estiver parando a Extrusão
