422:         public void UpdateStockProduction()
423:         {
424:             try
425:             {
426:                 DtBase eData = new DtBase(gsDataBaseFile, gsCulture);
427:                 Transports.Transp eTransport = new Transports.Transp(gsDataBaseFile, gsCulture, giUser);
428: 
429:                 eTransport.UpdateSiloPriorityProduct(giDestinationSilo, giSourceProduct);
430: 
431:                 if (giDestinationProduct == 0)
432:                     giDestinationProduct = giSourceProduct;
433: 
434:                 Decimal dTotalStock = gdDelivered * giPVBag;
435: 
436:                 Decimal dSourceStockDifference = Convert.ToDecimal(eData.GetSelectData("Select ps_stock from silo where cd_silo = " + Convert.ToString(giSourceSilo)));
437: 
438:                 // Balanceamento do Silo de Origem
439:                 Silo eSiloSource = new Silo(gsDataBaseFile, gsCulture, 0, giSourceSilo, 0);
440: 
441:                 if (dSourceStockDifference < dTotalStock)
442:                     eSiloSource.BalanceSilo(giSourceSilo, -Convert.ToDouble(dSourceStockDifference));
443:                 else
444:                     eSiloSource.BalanceSilo(giSourceSilo, -Convert.ToDouble(dTotalStock));
445: 
446:                 giPerformStep += 1;
447: 
448:                 ArrayList eDestinationSilo = new ArrayList();
449:                 Transports.Transp eTransports = new Transports.Transp(gsDataBaseFile, gsCulture, 0);
450: 
451:                 Silo eSilo = new Silo(gsDataBaseFile, gsCulture, 0, giDestinationSilo, giDestinationProduct);
452:                 Silo eSourceSilo = new Silo(gsDataBaseFile, gsCulture, 0, giSourceSilo, giSourceProduct);
453: 
454:                 if (giSourceProduct != giDestinationProduct && giDestinationProduct != 0)
455:                 {
456:                     eSourceSilo.Balance(Silo.BalanceType.btRealUse, Silo.BalanceStock.bsSilo, Convert.ToDouble(dTotalStock));
457:                     eSourceSilo.Balance(Silo.BalanceType.btTheoreticalUse, Silo.BalanceStock.bsSilo, Convert.ToDouble(dTotalStock));
458:                     
459:                     eSilo.Balance(Silo.BalanceType.btRealProduction, Silo.BalanceStock.bsSilo, Convert.ToDouble(dTotalStock));
460:                     eSilo.Balance(Silo.BalanceType.btTheoreticalProduction, Silo.BalanceStock.bsSilo, Convert.ToDouble(dTotalStock));
461:                 }
462: 
463:                 giPerformStep += 1;
464: 
465:                 // Faz o balanceamento do silo de destino
466:                 eSilo.BalanceSilo(giDestinationSilo, Convert.ToDouble(dTotalStock));
467: 
468:                 // Atualiza estoque de silo de origem da peletização caso ele esteja sendo usado
469:                 UpdatePelletlineStock(giDestinationSilo, Convert.ToDouble(dTotalStock));
470: 
471:                 PrintLabel.Print ePrint = new PrintLabel.Print(gsDataBaseFile, gsCulture, PrintLabel.Print.LabelType.BagFilling);
472:                 ePrint.ProductCode = Convert.ToString(giDestinationProduct);
473:                 ePrint.Code = gsBagFillingCode;
474:                 ePrint.Location = gsLocation;
475: 
476:                 int iBagNumber = Convert.ToInt32(eData.GetSelectData("Select vl_pv_bag from Bag_Filling_Scheduling where nr_production = " + gsProduction));
477: 
478:                 // For iBagNumber As Integer = iPVBag + 1 To iPVBag + Convert.ToInt32(giPVBag)
479: 
480:                 Traceability.TraceSiloExpedition(giDestinationSilo, Convert.ToInt32(gsProduction), iBagNumber, gdDelivered, Traceability.LotType.ltBaggingOff, gsDataBaseFile);
481: 
482:                 // Rastreabilidade de dosagem
483:                 Traceability.TraceDosing(Traceability.WeigherType.wtNormal, giSourceSilo, Convert.ToInt32(gsProduction), iBagNumber, 1, gdDelivered, gsDataBaseFile);
484: 
485:                 StopProductionDetailReg(gsProduction, Convert.ToString(iBagNumber));
486: 
487:                 // Se a ensacadora tiver uma impressora configurada
488:                 // imprime a etique para este bag
489:                 if (ePrint.IsEnabledPrinter()) ePrint.PrintThis(gsProduction, Convert.ToString(iBagNumber));
490: 
491:                 giPerformStep += 1;
492: 
493:                 // Next
494:             }
495:             catch (Exception ex)
496:             {
497:                 Utilities.Log(Convert.ToString(ex.Message) + Convert.ToString(ex.StackTrace), @"C:\Gemba\LOG\" + Utilities.GetApplicationName(), "Log ");
498:             }
499:         }

